];

if (rawEndpoints.length === 0) {
  rawEndpoints = defaultEndpoints;
} else {
  if (!rawEndpoints.some(e => e.action === 'export_store_report_excel')) {
    rawEndpoints.push(defaultEndpoints.find(e => e.action === 'export_store_report_excel'));
  }
  if (!rawEndpoints.some(e => e.action === 'get_revenue_chart')) {
    rawEndpoints.push(defaultEndpoints.find(e => e.action === 'get_revenue_chart'));
  }
}

function sanitizePII(text) {
  if (!text || typeof text !== 'string') return text;
  return text
    .replace(/\b(?:pin|otp|password|kata\s*sandi|token|secret)\s*[:=]\s*(\S+)/gi, (m, v) => m.replace(v, '[PIN/PASSWORD_DISAMARKAN]'))
    .replace(/\b\d{4}[ -]?\d{4}[ -]?\d{4}[ -]?\d{4}\b|\b\d{16}\b/g, '[NOMOR_KTP_DISAMARKAN]')
    .replace(/(?:\+?62|0)8[0-9]{1,3}[ -]?[0-9]{3,4}[ -]?[0-9]{3,5}\b/g, '[NOMOR_HP_DISAMARKAN]')
    .replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g, '[EMAIL_DISAMARKAN]')
    .replace(/\b(?:\d{4}[ -]?){3}\d{4}\b/g, '[KARTU_KREDIT_DISAMARKAN]');
}

const safeCapabilities = rawEndpoints.map(ep => ({
  action: ep.action,
  description: ep.description,
  params: ep.params || [],
  method: ep.method || 'GET',
  path: ep.path || '',
  current_data: ep.current_data || undefined
}));

const isExecutive = inputData.channel === 'whatsapp' || (inputData.role && inputData.role.includes('executive'));

let systemInstruction = '';

if (isExecutive) {
  systemInstruction = `Anda adalah EXECUTIVE AI ASSISTANT cerdas khusus untuk jajaran Direksi, C-Level, dan Manajer Operasional Perusahaan.\n\n`;
  systemInstruction += `🛡️ ATURAN PRIVASI & KEAMANAN KETAT (MANDATORY):\n`;
  systemInstruction += `- DILARANG KERAS membaca, menanyakan, meminta, atau menyimpan data pribadi sensitif (KTP/NIK, No HP, Password, PIN, Kartu Kredit).\n`;
  systemInstruction += `- Seluruh data sensitif yang masuk telah otomatis disamarkan (misal: [NOMOR_KTP_DISAMARKAN], [NOMOR_HP_DISAMARKAN]).\n\n`;
  systemInstruction += `👤 PROFIL EKSEKUTIF SAAT INI:\n`;
  systemInstruction += `- Nama / Jabatan: "${inputData.user_name || 'Bapak/Ibu Pimpinan'}"\n`;
  systemInstruction += `- User/WA ID: "${inputData.user_id || 'executive'}"\n`;
  systemInstruction += `- Kanal Komunikasi: WHATSAPP EKSEKUTIF (Executive BI Channel)\n\n`;
  systemInstruction += `🎯 GAYA KOMUNIKASI & PERSONA EKSEKUTIF (EXECUTIVE BRIEFING):\n`;
  systemInstruction += `1. Berikan respon yang lugas, padat, berbobot, to-the-point, dan berorientasi data keputusan (Executive Summary, ROI, Pertumbuhan, Tren Toko/Sistem, Excel, & Chart).\n`;
  systemInstruction += `2. Jika eksekutif meminta laporan dalam bentuk Excel, spreadsheet, atau unduhan data, WAJIB arahkan ke intent 'export_store_report_excel'.\n`;
  systemInstruction += `3. Jika eksekutif meminta grafik, chart visual, atau visualisasi tren revenue, WAJIB arahkan ke intent 'get_revenue_chart'.\n`;
  systemInstruction += `4. ⚠️ ATURAN FORMATTING WHATSAPP WAJIB (MANDATORY):\n`;
  systemInstruction += `   - Balasan DITAMPILKAN PADA APLIKASI WHATSAPP.\n`;
  systemInstruction += `   - WAJIB gunakan WhatsApp Markdown (*teks tebal*, _teks miring_, bullet •, dan monospace \`kode\`).\n`;
  systemInstruction += `   - DILARANG KERAS menggunakan tag HTML seperti <b>, <br>, <i>, <p>, <div> karena WhatsApp TIDAK MERENDER HTML! Gunakan baris baru (\\n) untuk jeda baris.\n`;
  systemInstruction += `5. KHUSUS LAPORAN KENDALA DARI EKSEKUTIF (report_customer_issue):\n`;
  systemInstruction += `   - Tetapkan urgensi 'darurat' / 'tinggi' (VIP Escalation) agar segera menjadi atensi prioritas engineering di Jira.\n\n`;
} else {
  systemInstruction = `Anda adalah AI INTENT PARSER cerdas untuk asisten percakapan sistem aplikasi web publik.\n\n`;
  systemInstruction += `🛡️ ATURAN PRIVASI & KEAMANAN KETAT (MANDATORY):\n`;
  systemInstruction += `- Anda DILARANG KERAS membaca, menanyakan, meminta, atau menyimpan data pribadi sensitif (seperti Nomor KTP/NIK, Nomor HP, Email, Password, PIN, Kartu Kredit).\n`;
  systemInstruction += `- Seluruh data sensitif yang masuk telah otomatis disamarkan (misalnya: [NOMOR_KTP_DISAMARKAN], [NOMOR_HP_DISAMARKAN], [PIN/PASSWORD_DISAMARKAN]).\n\n`;
  systemInstruction += `👤 INFORMASI PENGGUNA SAAT INI:\n`;
  systemInstruction += `- Nama Pengguna: "${inputData.user_name || 'Pelanggan'}"\n`;
  systemInstruction += `- User ID: "${inputData.user_id || 'guest'}"\n`;
  systemInstruction += `- Kanal: WEB WIDGET\n\n`;
  systemInstruction += `🎯 PERAN & TUGAS UTAMA:\n`;
  systemInstruction += `1. Anda bertugas MURNI SEBAGAI INTENT PARSER (Intent Recognition & Slot/Parameter Extraction).\n`;
  systemInstruction += `2. Analisis pesan pengguna terkini serta manfaatkan RIWAYAT MEMORI percakapan sebelumnya untuk memahami konteks multi-turn.\n`;
  systemInstruction += `3. Sapa pengguna dengan ramah, sebut nama mereka, pandu kendala operasional, dan buat tanggapan ramah dalam format HTML sederhana (<b>, <br>).\n\n`;
}

// 📚 DYNAMIC KNOWLEDGE BASE TEMPLATES DARI CMS (PROJECT MANAGEMENT)
const rawTemplates = manifestResp.support_templates || {};
const templateKeys = Object.keys(rawTemplates);

systemInstruction += `\n📚 PANDUAN KNOWLEDGE BASE DARI CMS (KASUS & SOLUSI RESMI PROJECT MANAGEMENT):\n`;
systemInstruction += `Jika pertanyaan atau keluhan pengguna cocok atau mirip dengan kasus di bawah ini, WAJIB utamakan memberikan panduan solusi terstruktur berikut:\n\n`;

if (templateKeys.length > 0) {
  templateKeys.forEach((key, idx) => {
    const tpl = rawTemplates[key];
    const topic = tpl.topic || key;
    const keywords = Array.isArray(tpl.keywords) ? tpl.keywords.join(', ') : '';
    const steps = Array.isArray(tpl.steps) ? tpl.steps.join('\n  ') : (tpl.raw_solution || '');
    const escalation = tpl.escalation || '';

    systemInstruction += `${idx + 1}. KASUS: "${topic}"\n`;
    systemInstruction += `- Intent Identifikasi: 'troubleshoot_${key}'\n`;
    if (keywords) {
      systemInstruction += `- Kata Kunci / Pertanyaan Terkait: ${keywords}\n`;
    }
    systemInstruction += `- Solusi yang Disampaikan ke Pengguna:\n  ${steps}\n`;
    if (escalation) {
      systemInstruction += `- Panduan Eskalasi: ${escalation}\n`;
    }
    systemInstruction += `\n`;
  });
}

systemInstruction += `📋 DAFTAR ACTION / KAPABILITAS SISTEM YANG TERSEDIA:\n`;
systemInstruction += JSON.stringify(safeCapabilities, null, 2) + `\n\n`;
systemInstruction += `DAFTAR INTENT PERCAKAPAN STANDAR:\n`;
systemInstruction += `- greeting: Salam / sapaan pembuka (halo, selamat pagi/siang, hai, dll.)\n`;
systemInstruction += `- export_store_report_excel: Meminta file laporan dalam bentuk spreadsheet Excel (.xlsx / .csv)\n`;
systemInstruction += `- get_revenue_chart: Meminta grafik visual, chart, atau tren penjualan bulanan\n`;
systemInstruction += `- report_customer_issue: Melaporkan masalah/kendala fitur sistem tidak dapat diakses atau bug\n`;
systemInstruction += `- ask_help: Menanyakan apa yang bisa dibantu atau fitur yang tersedia\n`;
systemInstruction += `- chitchat: Percakapan santai, terima kasih, ucapan penutup\n`;
systemInstruction += `- request_clarification: Jika maksud pengguna kurang jelas atau butuh informasi tambahan\n`;
systemInstruction += `- fallback_unknown: Jika di luar konteks sistem aplikasi\n\n`;
systemInstruction += `FORMAT OUTPUT WAJIB (HANYA JSON VALID, TANPA BACKTICK DI LUAR JSON):\n`;
systemInstruction += `{\n`;
systemInstruction += `  "intent": "<nama_action_atau_intent_standar>",\n`;
systemInstruction += `  "confidence": <skor_0_sampai_1>,\n`;
systemInstruction += `  "parameters": {\n`;
systemInstruction += `    "<key>": "<value>"\n`;
systemInstruction += `  },\n`;
systemInstruction += `  "requires_action": <true_jika_perlu_eksekusi_action_lainnya_false>,\n`;
systemInstruction += `  "matched_action": "<nama_action_terpilih_atau_null>",\n`;
systemInstruction += `  "context_note": "<catatan singkat pemahaman konteks dari memory jika multi-turn>",\n`;
systemInstruction += `  "reply": "<tanggapan sesuai channel: WhatsApp Markdown jika WhatsApp, HTML jika Web>"\n`;
systemInstruction += `}`; 

const contents = [];

historyMessages.forEach(msg => {
  contents.push({
    role: msg.role === 'assistant' ? 'model' : 'user',
    parts: [{ text: sanitizePII(msg.message) }]
  });
});

contents.push({
  role: 'user',
  parts: [{ text: inputData.message }]
});

// 🔑 Gemini API Key Pool & Rotasi Otomatis
const rawEnvKeys = ($env.GEMINI_API_KEYS || $env.GEMINI_API_KEY || "").trim();
const geminiKeys = rawEnvKeys
  .split(/[,;\s\n\r]+/)
  .map(k => k.trim())
  .filter(k => k.length > 8 && k !== "your_gemini_api_key_here");

let chosenKey = "";
let keyIndex = 0;

if (geminiKeys.length > 0) {
  const seedStr = (inputData.conversation_id || "") + "-" + Date.now() + "-" + Math.random();
  let hash = 0;
  for (let i = 0; i < seedStr.length; i++) {
    hash = ((hash << 5) - hash) + seedStr.charCodeAt(i);
    hash |= 0;
  }
  keyIndex = Math.abs(hash) % geminiKeys.length;
  chosenKey = geminiKeys[keyIndex];
} else {
  chosenKey = $env.GEMINI_API_KEY || "";
}

return [{
  json: {
    conversation_id: inputData.conversation_id,
    user_id: inputData.user_id,
    user_name: inputData.user_name,
    message: inputData.message,
    raw_message_has_pii: inputData.raw_message_has_pii,
    channel: inputData.channel,
    role: inputData.role || (inputData.channel === 'whatsapp' ? 'executive' : 'customer'),
    backend_base_url: inputData.backend_base_url,
    internal_api_key: inputData.internal_api_key,
    slack_webhook_url: inputData.slack_webhook_url,
    slack_channel: inputData.slack_channel,
    telegram_bot_token: inputData.telegram_bot_token,
    telegram_chat_id: inputData.telegram_chat_id,
    whatsapp_api_url: inputData.whatsapp_api_url,
    whatsapp_api_key: inputData.whatsapp_api_key,
    whatsapp_target_number: inputData.whatsapp_target_number,
    default_endpoints: rawEndpoints,
    gemini_api_key: chosenKey,
    key_pool: geminiKeys,
    key_index: keyIndex,
    payload: {
      systemInstruction: {
        parts: [{ text: systemInstruction }]
      },
      contents: contents,
      generationConfig: {
        temperature: 0.2,
        maxOutputTokens: 2048,
        responseMimeType: 'application/json',
        thinkingConfig: {
          thinkingBudget: 0
        }
      }
    }
  }
}];

const geminiResp = $input.first().json;
const promptData = $('Build Gemini Prompt').item.json;
const manifestResp = ($('Fetch AI Manifest') && $('Fetch AI Manifest').item && $('Fetch AI Manifest').item.json) || {};
const keyPool = Array.isArray(promptData.key_pool) ? promptData.key_pool : [];
let usedKeyIndex = promptData.key_index || 0;
let failoverSuccess = false;

const isExecutive = promptData.channel === 'whatsapp' || (promptData.role && promptData.role.includes('executive'));

// 🔄 Auto-Failover: Jika key terkena 429
if (geminiResp && geminiResp.error && keyPool.length > 1) {
  const isRateLimited = geminiResp.error.code === 429 ||
                        (geminiResp.error.message && /quota|exhausted|rate limit/i.test(geminiResp.error.message)) ||
                        geminiResp.error.status === "RESOURCE_EXHAUSTED";

  if (isRateLimited) {
    for (let i = 1; i < keyPool.length; i++) {
      const backupIndex = (usedKeyIndex + i) % keyPool.length;
      const backupKey = keyPool[backupIndex];
      try {
        const retryUrl = "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=" + backupKey;
        const retryRes = await fetch(retryUrl, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(promptData.payload)
        });
        const retryJson = await retryRes.json();
        if (retryJson && !retryJson.error && retryJson.candidates && retryJson.candidates.length > 0) {
          geminiResp = retryJson;
          usedKeyIndex = backupIndex;
          failoverSuccess = true;
          break;
        }
      } catch (err) {}
    }
  }
}

const endpoints = Array.isArray(manifestResp.endpoints) && manifestResp.endpoints.length > 0
  ? manifestResp.endpoints
  : (promptData.default_endpoints || []);

function extractJson(text) {
  if (!text) return null;
  const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  const candidate = match ? match[1].trim() : text.trim();
  try {
    return JSON.parse(candidate);
  } catch (e) {
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start !== -1 && end !== -1 && end > start) {
      try {
        return JSON.parse(text.substring(start, end + 1));
      } catch (err) {}
    }
  }
  return null;
}

let rawText = '';
let parsed = null;
if (geminiResp && geminiResp.candidates && geminiResp.candidates.length > 0) {
  const parts = geminiResp.candidates[0].content && geminiResp.candidates[0].content.parts;
  if (parts && parts.length > 0 && parts[0].text) {
    rawText = parts[0].text;
  }
} else if (geminiResp && geminiResp.error) {
  const userMsg = (promptData.message || '').toLowerCase();
  if (/excel|spreadsheet|unduh lap|download lap|format excel|file excel|laporan/i.test(userMsg)) {
    parsed = { intent: 'export_store_report_excel', matched_action: 'export_store_report_excel', confidence: 0.95 };
  } else if (/grafik|chart|kurva|visual|trend|tren|diagram/i.test(userMsg)) {
    parsed = { intent: 'get_revenue_chart', matched_action: 'get_revenue_chart', confidence: 0.95 };
  } else if (/ringkasan|summary|metrik|performa|saldo|kas|kasir|omset/i.test(userMsg)) {
    parsed = { intent: 'get_store_metrics', matched_action: 'get_store_metrics', requires_action: true, confidence: 0.95 };
  } else if (/tiket|kendala|masalah|gangguan|rusak|error|bug|komplain|lapor/i.test(userMsg)) {
    parsed = { intent: 'report_customer_issue', matched_action: 'report_customer_issue', requires_action: true, confidence: 0.95 };
  } else {
    rawText = JSON.stringify({ intent: 'error', reply: 'Kendala layanan AI: ' + (geminiResp.error.message || 'Error') });
  }
}

if (!parsed) {
  parsed = extractJson(rawText);
}

if (!parsed) {
  parsed = {
    intent: 'fallback_unknown',
    confidence: 0.5,
    parameters: {},
    requires_action: false,
    matched_action: null,
    reply: rawText || (isExecutive 
      ? 'Halo Pak/Bu Pimpinan. Ada yang bisa kami sajikan terkait ringkasan performa toko, metrik revenue, file laporan Excel, atau grafik penjualan hari ini?'
      : 'Halo! Ada yang bisa kami bantu terkait layanan atau informasi toko?')
  };
}

let finalReply = parsed.reply || '';
const targetAction = parsed.matched_action || parsed.intent;

let isTicketReport = false;
let ticketData = null;
let ticketNumber = '';

const displayName = promptData.user_name || promptData.user_id || (isExecutive ? 'Bapak/Ibu Pimpinan' : 'Pelanggan');

// Fulfillment Layer (Safe & Programmatic)
if (targetAction === 'report_customer_issue' || parsed.intent === 'report_customer_issue') {
  isTicketReport = true;
  const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  const randCode = Math.floor(1000 + Math.random() * 9000);
  ticketNumber = (parsed.parameters && parsed.parameters.ticket_number) || `TCK-${dateStr}-${randCode}`;

  const featureName = (parsed.parameters && parsed.parameters.feature_name) || 'Fitur Sistem';
  const category = (parsed.parameters && parsed.parameters.category) || 'fitur_tidak_dapat_diakses';
  const description = (parsed.parameters && parsed.parameters.description) || promptData.message;
  const urgency = isExecutive ? 'tinggi' : ((parsed.parameters && parsed.parameters.urgency) || 'tinggi');

  ticketData = {
    ticket_number: ticketNumber,
    conversation_id: promptData.conversation_id,
    user_id: promptData.user_id,
    user_name: promptData.user_name || '',
    category: category,
    feature_name: featureName,
    description: description,
    urgency: urgency,
    channel: promptData.channel || 'web'
  };

  if (isExecutive) {
    finalReply = `🎫 *ESKALASI INSIDEN EKSEKUTIF: #${ticketNumber}*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━\n` +
      `Yth. *${displayName}*, kendala pada *Fitur: ${featureName}* telah dicatat resmi dengan *PRIORITAS VIP*.\n\n` +
      `🌐 *Jira Service Desk*: Ditugaskan langsung ke antrean tim engineering (SUP).\n` +
      `🚨 *Alert Tim Teknis*: Notifikasi darurat telah dipancarkan ke Slack Tim Internal.\n\n` +
      `📋 *Rincian Kendala*:\n` +
      `• *No. Tiket*: \`#${ticketNumber}\`\n` +
      `• *Kategori*: ${category.replace(/_/g, ' ')}\n` +
      `• *Urgensi*: *${urgency.toUpperCase()} (VIP ESCALATION)*\n` +
      `• *Status*: *OPEN / INVESTIGASI AKTIF*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━\n` +
      `_Tim teknis segera menangani kendala ini dengan SLA percepatan._`;
  } else {
    finalReply = `🎫 <b>Tiket Laporan Gangguan Diterima: #${ticketNumber}</b><br><br>` +
      `Halo <b>${displayName}</b>, kendala terkait <b>Fitur: ${featureName}</b> telah kami catat resmi.<br><br>` +
      `🚨 <b>Pemberitahuan Tim Internal:</b><br>` +
      `Tiket ini telah diteruskan langsung ke <b>Jira Service Management (SUP)</b> & Slack Tim Internal untuk segera diinvestigasi oleh tim teknis.<br><br>` +
      `📋 <b>Rincian Tiket:</b><br>` +
      `• Nomor Tiket: <code>#${ticketNumber}</code><br>` +
      `• Kategori: <i>${category.replace(/_/g, ' ')}</i><br>` +
      `• Urgensi: <b>${urgency.toUpperCase()}</b><br>` +
      `• Status: <b style="color: #2563eb;">OPEN / SEDANG DITINDAKLANJUTI</b><br><br>` +
      `<small style="color: #64748b;">Simpan nomor tiket Anda. Tim teknis segera menangani kendala ini. Terima kasih atas laporannya!</small>`;
  }

} else if (targetAction === 'export_store_report_excel' || parsed.intent === 'export_store_report_excel') {
  const downloadUrl = (promptData.backend_base_url || 'http://127.0.0.1:8090') + '/api/v1/reports/store-metrics/excel';
  if (isExecutive) {
    finalReply = `📊 *FILE EXCEL LAPORAN BISNIS EKSEKUTIF*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━\n` +
      `Yth. *${displayName}*, rekap performa penjualan dan pendapatan bulanan telah siap dalam spreadsheet Excel (.csv / .xlsx):\n\n` +
      `📁 *Nama File*: \`Laporan_Eksekutif_Performa_2026.csv\`\n` +
      `📈 *Cakupan*: Data Orders, Gross Earnings, Refunds, dan Conversion Rate (Januari s/d Desember 2026)\n\n` +
      `📥 *Tautan Unduh Spreadsheet:*\n${downloadUrl}\n\n` +
      `━━━━━━━━━━━━━━━━━━━━━━\n` +
      `_File dapat dibuka langsung di Microsoft Excel, Apple Numbers, atau Google Sheets._`;
  } else {
    finalReply = `📊 <b>File Laporan Excel Toko</b><br><br>` +
      `Halo <b>${displayName}</b>, file laporan transaksi dan revenue Anda telah siap diunduh:<br><br>` +
      `📁 <b>File:</b> <code>Laporan_Eksekutif_Performa_2026.csv</code><br>` +
      `📥 <a href="${downloadUrl}" target="_blank" style="color:#2563eb; font-weight:600;">Klik di Sini untuk Mengunduh File Excel (.csv) ↗</a>`;
  }

} else if (targetAction === 'get_revenue_chart' || parsed.intent === 'get_revenue_chart') {
  const chartUrl = (promptData.backend_base_url || 'http://127.0.0.1:8090') + '/api/v1/reports/store-metrics/chart.png';
  if (isExecutive) {
    finalReply = `📈 *GRAFIK TREN PENJUALAN & REVENUE BULANAN*\n` +
      `━━━━━━━━━━━━━━━━━━━━━━\n` +
      `Yth. *${displayName}*, berikut visualisasi grafik performa penjualan tahun 2026:\n\n` +
      `📊 *Pratinjau Grafik Visual:*
${chartUrl}\n\n` +
      `• *Puncak Revenue*: Bulan April (*$108.87k*, 68 orders)\n` +
      `• *Bulan Terendah*: Bulan Agustus (*$28.57k*, 44 orders)\n` +
      `• *Rata-rata Bulanan*: ~$72.4k / bulan\n` +
      `━━━━━━━━━━━━━━━━━━━━━━\n` +
      `_Grafik terhubung langsung dengan Core Database analitik._`;
  } else {
    finalReply = `📈 <b>Grafik Tren Penjualan & Revenue:</b><br><br>` +
      `<img src="${chartUrl}" style="width:100%; border-radius:8px; margin-bottom:8px; border:1px solid #e2e8f0;" alt="Grafik Revenue"><br>` +
      `• Puncak penjualan tercatat pada bulan <b>April ($108.87k)</b>.`;
  }

} else if (parsed.requires_action && targetAction) {
  const endpointDef = endpoints.find(e => e.action === targetAction);
  if (endpointDef && endpointDef.current_data) {
    const data = endpointDef.current_data;
    if (targetAction === 'get_store_metrics') {
      if (isExecutive) {
        finalReply = `📊 *EXECUTIVE SUMMARY: PERFORMA BISNIS*\n` +
          `━━━━━━━━━━━━━━━━━━━━━━\n` +
          `• *Total Earnings*: *${data.total_earnings || '-'}*\n` +
          `• *Total Orders*: *${data.orders || '-'}*\n` +
          `• *Customers*: *${data.customers || '-'}*\n` +
          `• *Saldo Kas*: *${data.my_balance || '-'}*\n` +
          `• *Rasio Konversi*: *${data.conversion_ratio || '-'}*\n` +
          `• *Aktivitas Terkini*: ${data.recent_summary || '-'}\n` +
          `━━━━━━━━━━━━━━━━━━━━━━\n` +
          `_Data tersinkronisasi real-time dari Core Database._`;
      } else {
        finalReply = `📊 <b>Ringkasan Metrik Toko:</b><br>` +
          `• Total Earnings: <b>${data.total_earnings || '-'}</b><br>` +
          `• Total Orders: <b>${data.orders || '-'}</b><br>` +
          `• Customers: <b>${data.customers || '-'}</b><br>` +
          `• Saldo Toko: <b>${data.my_balance || '-'}</b><br>` +
          `• Rasio Konversi: <b>${data.conversion_ratio || '-'}</b>`;
      }
    } else if (targetAction === 'get_monthly_revenue') {
      const monthParam = (parsed.parameters && parsed.parameters.month) ? String(parsed.parameters.month).substring(0, 3).toLowerCase() : null;
      let matchedMonthKey = null;
      if (monthParam) {
        matchedMonthKey = Object.keys(data).find(k => k.toLowerCase().startsWith(monthParam));
      }

      if (isExecutive) {
        if (matchedMonthKey && data[matchedMonthKey]) {
          const mData = data[matchedMonthKey];
          finalReply = `📈 *EXECUTIVE BRIEFING: REVENUE BULAN ${matchedMonthKey.toUpperCase()}*\n` +
            `━━━━━━━━━━━━━━━━━━━━━━\n` +
            `• *Total Orders*: *${mData.orders}*\n` +
            `• *Earnings*: *${mData.earnings}*\n` +
            `• *Refunds*: *${mData.refunds}*\n` +
            `━━━━━━━━━━━━━━━━━━━━━━`;
        } else {
          const sampleMonths = Object.keys(data).slice(0, 4);
          finalReply = `📈 *EXECUTIVE BRIEFING: TREN REVENUE TOKO*\n` +
            `━━━━━━━━━━━━━━━━━━━━━━\n` +
            sampleMonths.map(m => `• *${m}*: ${data[m].earnings} (${data[m].orders} orders)`).join('\n') +
            `\n━━━━━━━━━━━━━━━━━━━━━━\n` +
            `_Ketik nama bulan tertentu (misal: "April" atau "Mei") untuk rincian mendalam._`;
        }
      } else {
        if (matchedMonthKey && data[matchedMonthKey]) {
          const mData = data[matchedMonthKey];
          finalReply = `📈 <b>Performa Revenue Bulan ${matchedMonthKey}:</b><br>` +
            `• Orders: <b>${mData.orders}</b><br>` +
            `• Earnings: <b>${mData.earnings}</b><br>` +
            `• Refunds: <b>${mData.refunds}</b>`;
        } else {
          const sampleMonths = Object.keys(data).slice(0, 4);
          finalReply = `📈 <b>Ringkasan Performa Revenue:</b><br>` +
            sampleMonths.map(m => `• <b>${m}</b>: ${data[m].earnings} (${data[m].orders} orders)`).join('<br>') +
            `<br><small>Sebutkan nama bulan tertentu (misal: April, Mei) untuk rincian lebih detail.</small>`;
        }
      }
    } else {
      if (isExecutive) {
        let title = endpointDef.description || targetAction.replace(/_/g, " ");
        let lines = [`📊 *${title.toUpperCase()}:*`];
        for (const [k, v] of Object.entries(data)) {
          lines.push(`• *${k.replace(/_/g, ' ')}*: ${v}`);
        }
        finalReply = (parsed.reply ? `${parsed.reply}\n\n` : "") + lines.join("\n");
      } else {
        let title = endpointDef.description || targetAction.replace(/_/g, " ");
        let lines = [`📊 <b>${title.charAt(0).toUpperCase() + title.slice(1)}:</b>`];
        for (const [k, v] of Object.entries(data)) {
          lines.push(`• <b>${k.replace(/_/g, ' ')}:</b> ${v}`);
        }
        finalReply = (parsed.reply ? `${parsed.reply}<br><br>` : "") + lines.join("<br>");
      }
    }
  }
}

// Format sanitasi akhir: Jika WhatsApp, pastikan tidak ada tag HTML mentah yang lolos
if (isExecutive) {
  finalReply = finalReply
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<(?:b|strong)>(.*?)<\/(?:b|strong)>/gis, '*$1*')
    .replace(/<(?:i|em)>(.*?)<\/(?:i|em)>/gis, '_$1_')
    .replace(/<code>(.*?)<\/code>/gis, '`$1`')
    .replace(/<li[^>]*>(.*?)<\/li>/gis, '• $1\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .trim();

  if (promptData.raw_message_has_pii) {
    finalReply += `\n\n_🛡️ Catatan Privasi: Data sensitif (KTP/No HP) otomatis disamarkan sebelum diproses AI._`;
  }
} else {
  if (promptData.raw_message_has_pii) {
    finalReply += `<br><br><small style="color: #64748b;">🛡️ <i>Catatan Privasi: Data pribadi sensitif (KTP/Nomor HP) Anda otomatis disamarkan sebelum diproses AI.</i></small>`;
  }
}

const usage = (geminiResp && geminiResp.usageMetadata) ? geminiResp.usageMetadata : {};
const promptTokens = usage.promptTokenCount || 0;
const candidatesTokens = usage.candidatesTokenCount || 0;
const totalTokens = usage.totalTokenCount || (promptTokens + candidatesTokens);

return [{
  json: {
    conversation_id: promptData.conversation_id,
    user_id: promptData.user_id,
    user_name: promptData.user_name || '',
    user_message: promptData.message,
    reply: finalReply,
    intent: parsed.intent || 'unknown',
    confidence: parsed.confidence || 0,
    parameters: parsed.parameters || {},
    matched_action: parsed.matched_action || null,
    context_note: parsed.context_note || '',
    pii_sanitized: Boolean(promptData.raw_message_has_pii),
    is_ticket_report: isTicketReport,
    ticket_number: ticketNumber,
    ticket_data: ticketData,
    channel: promptData.channel,
    role: promptData.role,
    backend_base_url: promptData.backend_base_url,
    internal_api_key: promptData.internal_api_key,
    slack_webhook_url: promptData.slack_webhook_url,
    slack_channel: promptData.slack_channel,
    telegram_bot_token: promptData.telegram_bot_token,
    telegram_chat_id: promptData.telegram_chat_id,
    whatsapp_api_url: promptData.whatsapp_api_url,
    whatsapp_api_key: promptData.whatsapp_api_key,
    whatsapp_target_number: promptData.whatsapp_target_number,
    tokens: {
      prompt_tokens: promptTokens,
      candidates_tokens: candidatesTokens,
      total_tokens: totalTokens,
      model: "gemini-2.5-flash",
      key_index: usedKeyIndex,
      key_failover: failoverSuccess,
      total_pool_keys: keyPool.length
    }
  }
}];

